/**
 * The batching nudge: five shell calls in a row, each alone in its request, earn the main session one
 * reminder to batch. `nudgeFor` is pure. `nudge` keeps an append-only list of call times per session: the
 * hooks of one message run concurrently, so each appends its own time first and decides from what it then
 * reads, never from a record it read before the others wrote. It never throws.
 *
 * Generated by Claude Code at the user's request.
 */

'use strict';

const fs = require('fs');
const path = require('path');

const { CACHE_DIR, prune, logError } = require('./cache');

/** Calls closer than this were sent together, in one message. */
const SAME_REQUEST_MS = 1500;
const IDLE_MS = 10 * 60 * 1000;
const RUN_LENGTH = 5;
const TEXT = '5 shell calls in a row, one per request: send independent ones in one message, chain dependent ones in one command.';
const LOG = path.join(CACHE_DIR, 'batch-nudge.log');
const LOG_MAX_BYTES = 16 * 1024;
const STALE_MS = 60 * 60 * 1000;
const HISTORY_MAX = 200;
/** Before delivering, wait for the hooks of the same message that started a moment later to append theirs. */
const SETTLE_MS = 500;

/** `record`: `{ run, last, nudged }` or null. Returns the next record and the text to deliver (or null). */
function nudgeFor(record, now) {
  let current = record ?? { run: 0, last: -Infinity, nudged: false };
  if (now - current.last > IDLE_MS) current = { run: 0, last: -Infinity, nudged: false };
  if (now - current.last <= SAME_REQUEST_MS) return { record: { run: 0, last: now, nudged: false }, text: null };

  const run = current.run + 1;
  const due = run >= RUN_LENGTH && !current.nudged;
  return { record: { run, last: now, nudged: current.nudged || due }, text: due ? TEXT : null };
}

function readTimes(file) {
  return fs.readFileSync(file, 'utf8').split('\n').filter(Boolean).map(Number).filter(Number.isFinite).sort((a, b) => a - b);
}

/** The text for the call at `now` and the record after it, folding every call up to it; a later call of the same request cancels it. */
function decide(times, now) {
  // A concurrent trim may have dropped this call's own line: no decision rather than a neighbour's nudge.
  if (!times.includes(now)) return { record: null, text: null };
  let step = { record: null, text: null };
  for (const time of times) if (time <= now) step = nudgeFor(step.record, time);
  const joinedLater = times.some((time) => time > now && time - now <= SAME_REQUEST_MS);
  return { record: step.record, text: joinedLater ? null : step.text };
}

/** Keep the newest calls only, replacing the file in one rename. */
function trim(file, times) {
  if (times.length <= HISTORY_MAX) return;
  const tmp = `${file}.${process.pid}.tmp`;
  fs.writeFileSync(tmp, times.slice(-HISTORY_MAX / 2).map((time) => `${time}\n`).join(''));
  fs.renameSync(tmp, file);
}

/** One line per nudge, capped like the error log; a failing log never loses the nudge. */
function appendLog(entry) {
  try {
    if (fs.existsSync(LOG) && fs.statSync(LOG).size > LOG_MAX_BYTES) {
      const tail = fs.readFileSync(LOG, 'utf8').slice(-LOG_MAX_BYTES / 2);
      fs.writeFileSync(LOG, tail.slice(tail.indexOf('\n') + 1));
    }
    fs.appendFileSync(LOG, `${JSON.stringify(entry)}\n`);
  } catch (error) {
    logError('guard-shell/batch-nudge-log', error);
  }
}

/** The text to add to this call's answer, or null: no session, a subagent, the first four calls, or any I/O error. */
function nudge(payload, now = Date.now(), settleMs = SETTLE_MS) {
  try {
    const session = String(payload?.session_id ?? '').replace(/[^\w-]/g, '');
    if (!session || payload.agent_type) return null;
    const file = path.join(CACHE_DIR, `batch-nudge-${session}.txt`);
    fs.mkdirSync(CACHE_DIR, { recursive: true });
    fs.appendFileSync(file, `${now}\n`);

    let times = readTimes(file);
    trim(file, times);
    prune(/^batch-nudge-.+\.txt(?:\.\d+\.tmp)?$/, now, STALE_MS);
    let result = decide(times, now);
    if (result.text) {
      Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, settleMs);
      times = readTimes(file);
      result = decide(times, now);
    }
    if (!result.text) return null;
    appendLog({ at: new Date(now).toISOString(), session, run: result.record.run });
    return result.text;
  } catch (error) {
    logError('guard-shell/batch-nudge', error);
    return null;
  }
}

module.exports = { nudgeFor, nudge };
